def _self_approval_workflow_keys():
    # کلید گردش‌هایی که تنظیم قدیمی شرکتی «تأیید سند خود» را می‌خواندند؛ از رجیستری، تا هسته نام ماژول ننویسد (ق۱)
    from workflow.registry import workflow_specs
    return sorted(k for k, spec in workflow_specs().items() if spec.company_self_approval)


def copy_self_approval(apps, schema_editor):
    """فقط ساختن ردیف: شرکت با creator_may_approve_own=True → ردیف تنظیم هر گردش company_self_approval."""
    Settings = apps.get_model('workflow', 'WorkflowCompanySettings')
    Policy = apps.get_model('workflow', 'WorkflowPolicy')
    company_ids = list(Settings.objects.filter(creator_may_approve_own=True).values_list('company_id', flat=True))
    if not company_ids:
        return
    for key in _self_approval_workflow_keys():
        for company_id in company_ids:
            Policy.objects.get_or_create(company_id=company_id, workflow_key=key,
                                         defaults={'creator_may_approve_own': True})


def mark_forced_tasks(apps, schema_editor):
    """
    کار مرحلهٔ باز اجباری امروز forced=True می‌گیرد: باز شده با open_at_step (ردیف auto همان کار بی from_step)
    یا آخرین مرحلهٔ اجباری تغییر نسخه (ردیف auto از مرحلهٔ حذف‌شده به آخرین مرحله).
    """
    Task = apps.get_model('workflow', 'WorkflowTask')
    Step = apps.get_model('workflow', 'WorkflowStep')
    open_tasks = {t.pk: t for t in Task.objects.filter(is_open=True, track='step').select_related('instance')}
    if not open_tasks:
        return
    forced = set()
    rows = Step.objects.filter(action='auto', task_id__in=list(open_tasks)).values_list('task_id', 'from_step', 'to_step')
    for task_id, from_step, to_step in rows:
        keys = list(open_tasks[task_id].instance.step_keys or [])
        if not from_step:
            forced.add(task_id)
        elif keys and from_step not in keys and to_step == keys[-1]:
            forced.add(task_id)
    if forced:
        Task.objects.filter(pk__in=forced).update(forced=True)


